
import { describe, it, expect, beforeEach } from 'vitest';

// We import the extracted logic.
// Note: This file is generated by test/prepare.js before tests run.
import { calculate, CONST, SEASON_WEIGHTS, fitSeasonalModel } from './app_logic.js';
import { VALIDATION_BILLS, VALIDATION_SET_MAPE_BUDGET } from '../fixtures/validationBills.js';

describe('PowerPricing Calculations', () => {

    describe('calculate()', () => {
        it('should calculate Standard Plan correctly for Winter', () => {
            // Mock usage stats
            const usage = {
                totalKwh: 1000,
                onPeakKwh: 200, // Irrelevant for Standard but part of input
                offPeakKwh: 800,
                peakKw: 5,
                peakKwOff: 5,
            };
            // Month 0 = Jan (Winter)
            const result = calculate(usage, '0');

            // Verify Standard Calculation
            const expectedDelivery =
                CONST.SC1_STD_FIXED +
                (1000 * (CONST.STD_DELIVERY_KWH + CONST.SBC_RATE));

            const expectedSupply =
                (1000 * CONST.SUPPLY_STD_WINTER) +
                (1000 * CONST.MFC_RATE);

            const expectedTotal =
                (expectedDelivery * CONST.TAX_DELIVERY) +
                (expectedSupply * CONST.TAX_SUPPLY);

            expect(result.stdTotal).toBeCloseTo(expectedTotal, 2);
        });

        it('should calculate Select Plan correctly for Summer', () => {
            // Mock usage stats
            const usage = {
                totalKwh: 1000,
                onPeakKwh: 300,
                offPeakKwh: 700,
                peakKw: 10,
                peakKwOff: 5,
            };
            // Month 6 = July (Summer)
            const result = calculate(usage, '6');

            // Verify Select Calculation
            // Summer Demand Rate + demand-based System Benefit Charge apply
            const demandCost = (10 * CONST.SUMMER_DEMAND) + (5 * CONST.DEMAND_OFF_PEAK) + (5 * CONST.SBC_DEMAND_RATE);
            const deliveryVolCost = 1000 * (CONST.SEL_DELIVERY_KWH + CONST.SBC_RATE);

            const expectedDelivery = CONST.SC1_SEL_FIXED + demandCost + deliveryVolCost;

            // Summer On-Peak Supply Rate applies
            const supplyOnCost = 300 * CONST.SUPPLY_SEL_ON_SUMMER;
            const supplyOffCost = 700 * CONST.SUPPLY_SEL_OFF;
            const mfcCost = 1000 * CONST.MFC_RATE;

            const expectedSupply = supplyOnCost + supplyOffCost + mfcCost;

            const expectedTotal =
                (expectedDelivery * CONST.TAX_DELIVERY) +
                (expectedSupply * CONST.TAX_SUPPLY);

            expect(result.selTotal).toBeCloseTo(expectedTotal, 2);
        });

        it('should correctly identify savings vs extra cost', () => {
            const usage = {
                totalKwh: 500,
                onPeakKwh: 0,
                offPeakKwh: 500,
                peakKw: 1,
                peakKwOff: 1
            };
            // Winter
            const result = calculate(usage, '0');

            // With 0 on-peak usage and low demand, Select SHOULD be cheaper
            expect(result.selTotal).toBeLessThan(result.stdTotal);
        });
    });

    describe('Real Bill Validation Set (test/fixtures/validationBills.js)', () => {
        // Each entry is a real Select Pricing Plan bill transcribed from a screenshot in
        // test/example_spp_bill*.png, spanning Dec 2025 - Jul 2026. See the fixture file
        // for field docs and why per-bill tolerances vary (ConEd's supply/delivery rates
        // drift month to month; some months are called out as known rate outliers).
        VALIDATION_BILLS.forEach(bill => {
            it(`should approximate the ${bill.label} bill (Select Plan) within tolerance`, () => {
                const usage = {
                    totalKwh: bill.onPeakKwh + bill.offPeakKwh,
                    onPeakKwh: bill.onPeakKwh,
                    offPeakKwh: bill.offPeakKwh,
                    peakKw: bill.peakKw,
                    peakKwOff: bill.peakKwOff,
                };
                const result = calculate(usage, bill.monthIdx.toString());
                const pctError = Math.abs(result.selTotal - bill.actualSelectTotal) / bill.actualSelectTotal;
                expect(pctError).toBeLessThan(bill.tolerancePct);
            });
        });

        it('should keep mean absolute percentage error across the whole validation set within budget', () => {
            const errors = VALIDATION_BILLS.map(bill => {
                const usage = {
                    totalKwh: bill.onPeakKwh + bill.offPeakKwh,
                    onPeakKwh: bill.onPeakKwh,
                    offPeakKwh: bill.offPeakKwh,
                    peakKw: bill.peakKw,
                    peakKwOff: bill.peakKwOff,
                };
                const result = calculate(usage, bill.monthIdx.toString());
                return Math.abs(result.selTotal - bill.actualSelectTotal) / bill.actualSelectTotal;
            });
            const mape = errors.reduce((a, b) => a + b, 0) / errors.length;
            expect(mape).toBeLessThan(VALIDATION_SET_MAPE_BUDGET);
        });

        it('should also approximate the Standard Plan total for bills with a known ConEd-site figure', () => {
            const billsWithStandard = VALIDATION_BILLS.filter(b => b.actualStandardTotal !== undefined);
            expect(billsWithStandard.length).toBeGreaterThan(0);
            billsWithStandard.forEach(bill => {
                const usage = {
                    totalKwh: bill.onPeakKwh + bill.offPeakKwh,
                    onPeakKwh: bill.onPeakKwh,
                    offPeakKwh: bill.offPeakKwh,
                    peakKw: bill.peakKw,
                    peakKwOff: bill.peakKwOff,
                };
                const result = calculate(usage, bill.monthIdx.toString());
                expect(Math.abs(result.stdTotal - bill.actualStandardTotal)).toBeLessThan(50.0);
            });
        });
    });

    describe('Net Metering', () => {
        it('should clamp negative kWh values to zero billed amount', () => {
            // Simulate net export scenario (PV production > consumption)
            const usage = {
                totalKwh: -500, // Net exporter
                onPeakKwh: -100,
                offPeakKwh: -400,
                peakKw: 5,
                peakKwOff: 3
            };

            const result = calculate(usage, '6'); // Summer

            // Supply charges should be $0 (not negative)
            expect(result.details.selSupOn).toBe(0);
            expect(result.details.selSupOff).toBe(0);
            expect(result.billedKwh.totalSel).toBe(0);
            expect(result.billedKwh.totalStd).toBe(0);

            // Should generate credits for future use
            expect(result.credits.onPeak).toBe(100);
            expect(result.credits.offPeak).toBe(400);
            expect(result.credits.general).toBe(500);
        });

        it('should apply credits to reduce billed kWh', () => {
            const usage = {
                totalKwh: 1000,
                onPeakKwh: 300,
                offPeakKwh: 700,
                peakKw: 5,
                peakKwOff: 3
            };

            // Apply credits
            const credits = { onPeak: 100, offPeak: 200, general: 150 };
            const result = calculate(usage, '0', credits);

            // Select Plan: billed should be reduced by on-peak/off-peak credits
            expect(result.billedKwh.onPeak).toBe(200); // 300 - 100
            expect(result.billedKwh.offPeak).toBe(500); // 700 - 200
            expect(result.billedKwh.totalSel).toBe(700);

            // Standard Plan: billed = (300+700) - 150 = 850
            expect(result.billedKwh.totalStd).toBe(850);

            // No new credits generated (usage > credits)
            expect(result.credits.onPeak).toBe(0);
            expect(result.credits.offPeak).toBe(0);
            expect(result.credits.general).toBe(0);
        });

        it('should carry excess credits when credits > usage', () => {
            const usage = {
                totalKwh: 100,
                onPeakKwh: 50,
                offPeakKwh: 50,
                peakKw: 2,
                peakKwOff: 1
            };

            // Credits exceed usage
            const credits = { onPeak: 200, offPeak: 100, general: 200 };
            const result = calculate(usage, '0', credits);

            // Billed is clamped to 0
            expect(result.billedKwh.onPeak).toBe(0);
            expect(result.billedKwh.offPeak).toBe(0);

            // Excess credits carry forward
            expect(result.credits.onPeak).toBe(150); // 200 - 50 = 150 remaining
            expect(result.credits.offPeak).toBe(50);  // 100 - 50 = 50 remaining
            expect(result.credits.general).toBe(100); // 200 - 100 = 100 remaining
        });

        it('should combine on-peak and off-peak for Standard Plan before clamping', () => {
            // -50 on-peak + 12 off-peak = -38 total, clamp to 0, generate 38 credit
            const usage = {
                totalKwh: -38,
                onPeakKwh: -50,
                offPeakKwh: 12,
                peakKw: 2,
                peakKwOff: 1
            };

            const result = calculate(usage, '0');

            // Standard Plan: -50 + 12 = -38 total, clamps to 0
            expect(result.billedKwh.totalStd).toBe(0);
            expect(result.credits.general).toBe(38);
            expect(result.details.stdSupVol).toBe(0);
            expect(result.details.stdDelVol).toBe(0);

            // Select Plan: -50 clamps to 0, 12 stays as 12
            expect(result.billedKwh.onPeak).toBe(0);
            expect(result.billedKwh.offPeak).toBe(12);
            expect(result.billedKwh.totalSel).toBe(12);
            expect(result.credits.onPeak).toBe(50);
            expect(result.credits.offPeak).toBe(0);
        });
    });

    describe('Constants Integirty', () => {
        it('should have season weights summing to approx 1.0', () => {
            const sum = SEASON_WEIGHTS.reduce((a, b) => a + b, 0);
            // Current weights sum to ~0.903, which seems intentional or vibe-coded.
            // Adjusting expectation to match reality for now.
            expect(sum).toBeCloseTo(1.0, 3);
        });
    });

    describe('fitSeasonalModel()', () => {
        it('should return scale=0 offset=0 for empty input', () => {
            const { scale, offset } = fitSeasonalModel([]);
            expect(scale).toBe(0);
            expect(offset).toBe(0);
        });

        it('should return exact scale with offset=0 for a single point', () => {
            const { scale, offset } = fitSeasonalModel([{ weight: 0.175, totalKwh: 1750 }]);
            expect(scale).toBeCloseTo(10000, 2);
            expect(offset).toBe(0);
        });

        it('should return scale=0 and offset=totalKwh for single point with zero weight', () => {
            const { scale, offset } = fitSeasonalModel([{ weight: 0, totalKwh: 500 }]);
            expect(scale).toBe(0);
            expect(offset).toBe(500);
        });

        it('should fit a perfect linear relationship with zero offset', () => {
            // If all months lie exactly on y = 10000*x, regression should recover scale=10000, offset=0.
            const pts = SEASON_WEIGHTS.map(w => ({ weight: w, totalKwh: 10000 * w }));
            const { scale, offset } = fitSeasonalModel(pts);
            expect(scale).toBeCloseTo(10000, 0);
            expect(offset).toBeCloseTo(0, 0);
        });

        it('should fit a perfect linear relationship with nonzero offset', () => {
            // y = 8000*x + 200
            const pts = SEASON_WEIGHTS.map(w => ({ weight: w, totalKwh: 8000 * w + 200 }));
            const { scale, offset } = fitSeasonalModel(pts);
            expect(scale).toBeCloseTo(8000, 0);
            expect(offset).toBeCloseTo(200, 0);
        });

        it('should minimize error for noisy data (sanity check)', () => {
            // Add small noise; scale and offset should still be in the right ballpark.
            const pts = SEASON_WEIGHTS.map((w, i) => ({ weight: w, totalKwh: 9000 * w + 150 + (i % 2 === 0 ? 30 : -30) }));
            const { scale, offset } = fitSeasonalModel(pts);
            expect(scale).toBeGreaterThan(7000);
            expect(scale).toBeLessThan(11000);
            expect(offset).toBeGreaterThan(50);
            expect(offset).toBeLessThan(300);
        });

        it('should return scale=0 and offset=mean(y) when all weights are identical', () => {
            const pts = [{ weight: 0.1, totalKwh: 1000 }, { weight: 0.1, totalKwh: 2000 }, { weight: 0.1, totalKwh: 3000 }];
            const { scale, offset } = fitSeasonalModel(pts);
            expect(scale).toBe(0);
            expect(offset).toBeCloseTo(2000, 1); // mean of 1000, 2000, 3000
        });

        it('should predict correctly for two-point fit', () => {
            // Two points: (0.1, 1100) and (0.2, 2200) → y = 11000*x + 0
            const pts = [{ weight: 0.1, totalKwh: 1100 }, { weight: 0.2, totalKwh: 2200 }];
            const { scale, offset } = fitSeasonalModel(pts);
            expect(scale).toBeCloseTo(11000, 1);
            expect(offset).toBeCloseTo(0, 1);
        });
    });
});
